const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Trent River area (Nottingham, UK)
  const trentRiver = ee.Geometry.Point([-1.15, 52.95]).buffer(10000); // 10km buffer around Nottingham

  // 2. Define time periods
  const floodStart = '2017-09-15';
  const floodEnd = '2017-09-20';
  const baselineStart = '2017-08-01';
  const baselineEnd = '2017-08-31';

  // 3. Get Sentinel-1 SAR data for flood period
  let floodCol = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(trentRiver)
    .filterDate(floodStart, floodEnd)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));

  const floodSize = floodCol.size().getInfo();
  console.log('Flood period images:', floodSize);

  if (floodSize === 0) {
    // Try Landsat 8 as fallback
    floodCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(trentRiver)
      .filterDate(floodStart, floodEnd)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    const floodSizeFallback = floodCol.size().getInfo();
    console.log('Fallback Landsat images:', floodSizeFallback);

    if (floodSizeFallback === 0) {
      console.log('No imagery available for flood period');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Get baseline SAR data
  let baselineCol = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(trentRiver)
    .filterDate(baselineStart, baselineEnd)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));

  const baselineSize = baselineCol.size().getInfo();
  console.log('Baseline period images:', baselineSize);

  if (baselineSize === 0) {
    console.log('No baseline imagery available');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Process SAR data - create water masks
  const floodImage = floodCol.mean().select('VV');
  const baselineImage = baselineCol.mean().select('VV');

  // Water has low backscatter (< -15 dB typically)
  const waterThreshold = -15;
  const floodWater = floodImage.lt(waterThreshold);
  const baselineWater = baselineImage.lt(waterThreshold);

  // 6. Calculate water extent areas
  const floodStats = floodWater.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: trentRiver,
    scale: 1000,
    maxPixels: 1e9
  });

  const baselineStats = baselineWater.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: trentRiver,
    scale: 1000,
    maxPixels: 1e9
  });

  const floodPixels = floodStats.get('VV').getInfo();
  const baselinePixels = baselineStats.get('VV').getInfo();

  console.log('Flood period water pixels:', floodPixels);
  console.log('Baseline water pixels:', baselinePixels);

  // 7. Validation and answer
  if (floodPixels === null || baselinePixels === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (floodPixels === 0 && baselinePixels === 0) {
    console.log('No valid water pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate percentage increase
  const increasePercent = ((floodPixels - baselinePixels) / baselinePixels) * 100;
  console.log('Water extent increase:', increasePercent.toFixed(2) + '%');

  // Flooding indicated by >30% increase in water extent
  if (increasePercent > 30) {
    console.log('Significant flooding detected');
    console.log('<answer>A</answer>');
  } else {
    console.log('No significant flooding detected');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
